from math import comb

# Function to calculate f(K_n) and g(K_n)
def calculate_metrics(n):
    f_kn = comb(n, 3)
    g_kn = comb(n, 4)
    return f_kn, g_kn

# Function to calculate the ratio R(K_n)
def calculate_ratio(f_kn, g_kn):
    if f_kn == 0:
        return None  # Avoid division by zero, though for n>=3, f(K_n) >= 1
    return (g_kn**3) / (f_kn**4)

# Calculate for n = 3, 4, 5, 6
results = {}
for n in range(3, 7):
    f, g = calculate_metrics(n)
    r = calculate_ratio(f, g)
    results[n] = {
        'f': f,
        'g': g,
        'ratio': r
    }
    print(f"K_{n}: f = {f}, g = {g}, Ratio = {r}")

# Find the maximum ratio
max_ratio = -1
max_n = -1
for n, res in results.items():
    if res['ratio'] > max_ratio:
        max_ratio = res['ratio']
        max_n = n

print(f"Maximum ratio found is: {max_ratio} for K_{max_n}")

from math import comb

results = {}
for n in range(9, 16):
    f_kn = comb(n, 3)
    g_kn = comb(n, 4)

    # Calculate R(K_n) = g(K_n)^3 / f(K_n)^4
    try:
        ratio = (g_kn**3) / (f_kn**4)
        results[n] = (f_kn, g_kn, ratio)
    except ZeroDivisionError:
        results[n] = (f_kn, g_kn, float('inf'))

print("Calculations for K_9 to K_15:")
for n, (f, g, r) in results.items():
    print(f"K_{n}: f(K_n)={f}, g(K_n)={g}, R(K_n)={r}")

